mapper.select:
select hcl.* from hls_credit_line hcl
where
1=1

    and hcl.source_document_category = #{sourceDocumentCategory}


    and hcl.source_document_id = #{sourceDocumentId}


    and hcl.company_id =#{companyId}

select
hcl.credit_line_status,
(
select scvb.MEANING
from sys_code_b scb, sys_code_value_b scvb
where scvb.CODE_ID = scb.CODE_ID
and scb.code = 'CON.CONTRACT_PROCESS_STATUS'
and scvb.value = hcl.credit_line_status
) as credit_line_status_value,
count(credit_line_id) as credit_line_count,
round(count(credit_line_id)/(select count(credit_line_id) from hls_credit_line

    1=1
    and business_type='CREDIT_LINE'

        and valid_from >= #{beginDate}


        and valid_to <= #{endDate}


        and company_id =#{companyId}


),2)*100 as credit_line_count_percent
from hls_credit_line hcl

    1=1
    and hcl.business_type='CREDIT_LINE'

        and valid_from >= #{beginDate}


        and valid_to <= #{endDate}


        and hcl.company_id =#{companyId}


group by hcl.credit_line_status

select tab.* from ( select hcl.credit_line_id, hcl.credit_line_number, hcl.credit_line_name, hcl.bp_id, hcl.company_id, hcl.document_type, hcl.document_category, hcl.proposer_user_id, hcl.proposer_employee_assign_id, hcl.proposer_employee_id, hcl.business_type, hcl.source_document_category, hcl.source_document_id, hcl.credit_line_status, hcl.currency_code, hcl.credit_line_amt, hcl.term, hcl.cancel_flag, hcl.source_credit_line_id, hcl.project_assistant_assigns_id, hcl.project_assistant, to_date(hcl.VALID_FROM,'YYYY-MM-DD')VALID_FROM, to_date(hcl.VALID_TO,'YYYY-MM-DD')VALID_TO, fe.NAME as project_assistant_name, HLS_CREDUT_LINE_CALC.credit_Used_Amt_clac(hcl.bp_id)creditUsedAmt, HLS_CREDUT_LINE_CALC.credit_Exposure_Amt(hcl.bp_id)credit_exposure_amt, HLS_CREDUT_LINE_CALC.credit_preemption_Amt(hcl.bp_id)credit_preemption_amt, ( select hbm.bp_name from hls_bp_master hbm where hcl.bp_id=hbm.bp_id )as credit_obj_name, ( select hbm.bp_name from hls_bp_master hbm where hcl.bp_id=hbm.bp_id )as bp_name, /*nvl((select sum(fp.credit_amount) from fct_project fp where fp.credit_line_id=hcl.credit_line_id),0) as credit_used_amt,*/ ( select hds.description from hls_document_status hds where hds.status_code=hcl.credit_line_status and hds.document_category=hcl.document_category )as credit_line_status_desc, ( select hdt.description from hls_document_type hdt where hdt.document_type=hcl.document_type and hdt.document_category=hcl.document_category and hdt.business_type=hcl.business_type )as document_desc from hls_credit_line hcl join fnd_employee fe on fe.EMPLOYEE_ID=hcl.PROJECT_ASSISTANT order by hcl.credit_line_id desc )tab
and tab.document_category='HLS_CREDIT_LINE' and tab.business_type='CREDIT_LINE' and tab.company_id =#{request.companyId} and ((sysdate between tab.VALID_FROM and tab.VALID_TO AND tab.credit_line_status ='APPROVED')or(tab.VALID_FROM is null and tab.credit_line_status in('NEW','APPROVED_RETURN'))) and (#{request.employeeCode}='ADMIN' or (((select fe.employee_id from fnd_employee fe where fe.employee_code=#{request.employeeCode} and fe.enabled_flag='Y' and fe.company_id=#{request.companyId}) in (tab.PROJECT_ASSISTANT,tab.PROPOSER_EMPLOYEE_ID)) or(exists (select 1 from hls_bp_master_role a,hls_credit_line b where a.bp_type='GROUP' and a.bp_id=b.bp_id and b.CREDIT_LINE_ID=tab.CREDIT_LINE_ID))))
and credit_line_status in ('APPROVED','NEW','APPROVED_RETURN')
and business_type = #{businessType}
and credit_line_status = #{creditLineStatus}
and credit_obj_name LIKE concat(concat('%',#{creditObjectName,jdbcType=VARCHAR}),'%')
and tab.credit_line_name LIKE concat(concat('%',#{creditLineName}),'%')
and tab.credit_line_number LIKE concat(concat('%',#{creditLineNumber}),'%')
and valid_from >= #{beginDate}
and valid_to <= #{endDate}
and credit_line_amt >= #{limitFrom}
and credit_line_amt <= #{limitTo}

select ( select hbt.description from hls_bp_master_role hbmr, hls_bp_type hbt where hbmr.bp_type=hbt.bp_type and hbmr.bp_id=hcl.bp_id and HBMR.CREATION_DATE <= (select min(a.CREATION_DATE) from hls_bp_master_role a where a.BP_ID=HCL.BP_ID ) and rownum=1 )as bp_type, HLS_CREDUT_LINE_CALC.credit_Used_Amt_clac(hcl.bp_id)credit_used_amount, HLS_CREDUT_LINE_CALC.credit_Exposure_Amt(hcl.bp_id)credit_exposure_amt, HLS_CREDUT_LINE_CALC.credit_preemption_Amt(hcl.bp_id)credit_preemption_amt, ( select fe.name from fnd_employee fe where fe.employee_id=hcl.proposer_employee_id )as project_manager, ( select fe.name from fnd_employee fe where fe.employee_id=hcl.project_assistant )as project_assistant_name, ( select fe.name from fnd_employee fe where fe.employee_id=hcl.project_assistant )as project_assistant_n, ( select hbm.bp_code from hls_bp_master hbm where hbm.bp_id=hcl.bp_id )as client_code, ( select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=hcl.bp_id )as client_name, ( select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=hcl.bp_id )as bp_id_n, ( select fou.unit_name from fnd_org_unit fou, fnd_employee_assigns fea where fea.employee_assign_id=hcl.proposer_employee_assign_id and fou.unit_id=fea.unit_id )as unitName, ( select wm_concat(d.name) from fnd_employee_assigns a1, fnd_employee_assigns a2, fnd_org_unit b, fnd_employee d where a1.employee_assign_id = hcl.proposer_employee_assign_id and a1.unit_id = b.unit_id and b.chief_position_id = a2.position_id and a2.employee_id = d.employee_id and a1.COMPANY_ID = a2.COMPANY_ID and a2.ENABLED_FLAG = 'Y' )as manager_name, ( select fc.company_full_name from fnd_company fc where fc.company_id=hcl.company_id )as company_name, ( select fc.currency_name from fnd_currency fc where fc.currency_code=hcl.currency_code )as currency_name, ( select fc.currency_name from fnd_currency fc where fc.currency_code=hcl.currency_code )as currency_code_n, ( select hdt.description from hls_document_type hdt where hdt.document_type=hcl.document_type and hdt.document_category=hcl.document_category and hdt.business_type=hcl.business_type )as document_desc, ( select hdt.description from hls_document_type hdt where hdt.document_type=hcl.document_type and hdt.document_category=hcl.document_category and hdt.business_type=hcl.business_type )as document_type_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scvb.value=hcl.credit_line_status and scb.code='CAP.APPROVE_STATUS' and scvb.code_id=scb.code_id ) as credit_line_status_desc, hcl.credit_line_name credit_line_name_n, hcl.* from hls_credit_line hcl
1=1
and hcl.credit_line_id = #{creditLineId}

mapper.update:
UPDATE hls_credit_line hcl SET
hcl.credit_line_status = 'APPROVED',
hcl.LAST_UPDATED_BY =#{userId},
hcl.LAST_UPDATE_DATE = #{date}
WHERE
hcl.source_document_category = #{sourceDocumentCategory}
AND hcl.source_document_id = #{sourceDocumentId}

mapper.select:
select tab.* from ( select hcl.*, ( select hbm.bp_name from hls_bp_master hbm where hcl.bp_id=hbm.bp_id )as credit_obj_name, ( select hds.description from hls_document_status hds where hds.status_code=hcl.credit_line_status and hds.document_category=hcl.document_category )as credit_line_status_desc from hls_credit_line hcl order by hcl.credit_line_id desc )tab
and tab.business_type='credit_line'
and tab.company_id =#{companyId}
AND tab.credit_line_status IN
#{item}
AND tab.document_type IN
#{item}
